    "id": "aic-3818",
    "title": "Ornament With Flower and Eight Wild Folk",
    "artist": "Israhel van Meckenem, the younger",
    "artistSort": "younger israhel van meckenem the younger",
    "year": "1490/1500",
    "yearStart": 1465,
    "yearEnd": 1503,
    "era": "Before 1700",
